"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["52317"],{68289(o){o.exports=JSON.parse('{"registro":{"codigo":"uniplus.configuracao.fato_valor_dominio.ja_ativo","status":422,"titulo":"O valor j\xe1 est\xe1 ativo"},"descricao":{"codigo":"uniplus.configuracao.fato_valor_dominio.ja_ativo","requisitos":[],"oQueAconteceu":["O administrador pediu a reativa\xe7\xe3o de um valor de um fato do cat\xe1logo (`POST /api/configuracao/admin/fatos-candidato/{id}/valores/{codigo}/ativacao`), mas o valor j\xe1 est\xe1 ativo. Todo valor acrescentado nasce ativo; s\xf3 a desativa\xe7\xe3o o deixa inativo. A recusa evita uma altera\xe7\xe3o sem efeito no fato.","As confer\xeancias seguem esta ordem: o fato (`uniplus.configuracao.fato_candidato.nao_encontrado`), a defini\xe7\xe3o do fato de sistema, que \xe9 travada (`uniplus.configuracao.fato_candidato.definicao_do_fato_de_sistema_travada`), o valor (`uniplus.configuracao.fato_valor_dominio.nao_encontrado`) e, por \xfaltimo, o estado do valor. S\xf3 um valor existente de um fato do administrador chega a esta recusa. Nada \xe9 gravado."],"comoResolver":["Nenhuma provid\xeancia \xe9 necess\xe1ria: o valor j\xe1 est\xe1 ativo e dispon\xedvel para novos v\xednculos. Se a inten\xe7\xe3o era outra, confira o c\xf3digo do valor."],"ondeAparece":["Reativa\xe7\xe3o de um valor de um fato do cat\xe1logo"]},"modulo":{"id":"configuracao","nome":"Configura\xe7\xe3o","assunto":"Fato valor dominio"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"e5dad467d85ce0f062b88f68241ad834bc540cf0"}}')}}]);